function evidence = f90_xtherm03_extract_candidate_evidence( ...
        modelPath, outputDir)
%F90_XTHERM03_EXTRACT_CANDIDATE_EVIDENCE Replay the public MSF contract.
arguments
    modelPath (1,1) string
    outputDir (1,1) string
end
[taskRoot, sharedRoot] = localRoots("F90-XTHERM-03");
addpath(sharedRoot, "-begin");
cleanup = onCleanup(@() rmpath(sharedRoot)); %#ok<NASGU>
official = jsondecode(fileread(simuverity_official_scenarios_path()));
spec = struct( ...
    "schema", "simuverity.formal90-fixed-evidence.v1", ...
    "task_id", "F90-XTHERM-03", ...
    "scenarios", official.scenarios, ...
    "output_contract", localOutputs, ...
    "input_builder", @localInputs, ...
    "requested_input_builder", @localRequested, ...
    "stop_time", @(~,~) double(official.simulation.stop_time_s), ...
    "postprocess", @localPostprocess, ...
    "static_audit", @localAudit, ...
    "finalize_evidence", @localFinalizeEvidence, ...
    "evidence_sample_s", 0.2);
evidence = simuverity_run_candidate_evidence( ...
    modelPath, outputDir, spec);
end

function rows = localOutputs
rows = localRows(["plant_state", "flow_state", "control_state"], ...
    [4 4 4]);
end

function inputs = localInputs(scenario, ~)
inputs = struct( ...
    "feed_temperature_C", double(scenario.feed_temperature_C), ...
    "recycle_brine_flow_ton_per_min", ...
        double(scenario.recycle_brine_flow_ton_per_min), ...
    "steam_feed_kg_per_min", double(scenario.steam_feed_kg_per_min), ...
    "top_brine_temperature_setpoint_C", ...
        double(scenario.top_brine_temperature_setpoint_C), ...
    "distillate_flow_setpoint_ton_per_min", ...
        double(scenario.distillate_flow_setpoint_ton_per_min), ...
    "disturbance_start_s", double(scenario.disturbance_start_s), ...
    "feed_temperature_step_C", ...
        double(scenario.feed_temperature_step_C), ...
    "recycle_flow_step_ton_per_min", ...
        double(scenario.recycle_flow_step_ton_per_min));
end

function requested = localRequested(scenario, ~)
requested = rmfield(scenario, "id");
end

function row = localPostprocess(row, outputs, scenario, ~)
t = double(outputs.time_s(:));
plant = double(outputs.plant_state);
flow = double(outputs.flow_state);
control = double(outputs.control_state);
tail = t >= max(t(1), t(end) - 0.2 * (t(end) - t(1)));
pre = t < double(scenario.disturbance_start_s) & ...
    t >= max(t(1), double(scenario.disturbance_start_s) - 30);
post = t >= double(scenario.disturbance_start_s);
if ~any(pre), pre = t <= t(1) + 0.2 * (t(end) - t(1)); end
row.outputs = outputs;
row.metrics = struct( ...
    "top_brine_tail_mae_C", median(abs(control(tail,3))), ...
    "distillate_tail_mae_ton_per_min", median(abs(control(tail,4))), ...
    "top_brine_peak_error_C", max(abs(control(post,3))), ...
    "distillate_peak_error_ton_per_min", max(abs(control(post,4))), ...
    "last_brine_level_min_m", min(plant(:,1)), ...
    "last_brine_level_max_m", max(plant(:,1)), ...
    "last_distillate_level_min_m", min(plant(:,4)), ...
    "last_distillate_level_max_m", max(plant(:,4)), ...
    "top_brine_temperature_span_C", ...
        max(plant(:,3)) - min(plant(:,3)), ...
    "distillate_flow_span_ton_per_min", ...
        max(flow(:,2)) - min(flow(:,2)), ...
    "steam_flow_span_kg_per_min", max(flow(:,4)) - min(flow(:,4)), ...
    "pre_top_brine_temperature_C", median(plant(pre,3)), ...
    "tail_top_brine_temperature_C", median(plant(tail,3)), ...
    "pre_distillate_flow_ton_per_min", median(flow(pre,2)), ...
    "tail_distillate_flow_ton_per_min", median(flow(tail,2)), ...
    "all_finite", all(isfinite([plant(:); flow(:); control(:)])));
row.valid = row.output_contract.all_required_pass && ...
    numel(t) >= 100 && t(1) <= 1e-9 && t(end) >= 299.8 && ...
    row.metrics.all_finite;
end

function audit = localAudit(model, spec)
names = string({spec.output_contract.name})';
structure = simuverity_candidate_structure(model, names);
semantic = structure.semantic_types;
controllerCount = nnz(contains(semantic, ...
    ["pid", "controller", "stateflow"]));
inputNames = ["feed_temperature_C", ...
    "recycle_brine_flow_ton_per_min", "steam_feed_kg_per_min", ...
    "top_brine_temperature_setpoint_C", ...
    "distillate_flow_setpoint_ton_per_min", "disturbance_start_s", ...
    "feed_temperature_step_C", "recycle_flow_step_ton_per_min"];
inputUsed = false(size(inputNames));
for k = 1:numel(inputNames)
    inputUsed(k) = localUsesVariable(model, inputNames(k));
end
allOutputs = structure.connected_output_count == numel(names) && ...
    structure.nontrivial_output_source_count == numel(names);
stageEvidence = max(structure.dynamic_block_count, ...
    floor(structure.physical_connection_block_count / 2));
audit = struct( ...
    "published_stage_count", min(22, stageEvidence), ...
    "plant_input_port_count", nnz(inputUsed(1:3)), ...
    "plant_output_port_count", 12 * double(allOutputs), ...
    "feedback_controller_count", controllerCount, ...
    "native_msf_sfunction", localNativeProcessFunction(model), ...
    "simulink_path_selected", true, ...
    "source_dependencies_complete", true, ...
    "temperature_feedback_connected", ...
        controllerCount >= 2 && structure.signal_cycle_present, ...
    "distillate_feedback_connected", ...
        controllerCount >= 2 && structure.signal_cycle_present, ...
    "public_input_usage_count", nnz(inputUsed), ...
    "connected_public_output_count", structure.connected_output_count, ...
    "core_path_qualified", all(inputUsed) && allOutputs && ...
        stageEvidence >= 22 && controllerCount >= 2 && ...
        structure.signal_cycle_present);
end

function evidence = localFinalizeEvidence(evidence, ~)
evidence.evidence_complete = logical(evidence.score_inputs_valid);
end

function value = localNativeProcessFunction(model)
value = "";
blocks = string(find_system(model, "LookUnderMasks", "all", ...
    "FollowLinks", "on", "BlockType", "S-Function"));
for block = blocks'
    try
        value = string(get_param(block, "FunctionName"));
        if strlength(value) > 0, return, end
    catch
    end
end
end

function tf = localUsesVariable(model, variable)
tf = false;
try
    tf = ~isempty(Simulink.findVars(model, "Name", char(variable)));
catch
end
end

function rows = localRows(names, widths)
rows = repmat(struct("name", "", "evidence_name", "", ...
    "width", 0, "interpolation", "linear"), numel(names), 1);
for k = 1:numel(names)
    rows(k).name = names(k);
    rows(k).evidence_name = names(k);
    rows(k).width = widths(k);
end
end

function [taskRoot, sharedRoot] = localRoots(taskId)
scriptRoot = fileparts(mfilename("fullpath"));
tasksRoot = fileparts(scriptRoot);
sharedRoot = fullfile(tasksRoot, "_shared");
repoRoot = tasksRoot;
for k = 1:3, repoRoot = fileparts(repoRoot); end
taskRoot = string(getenv("SIMUVERITY_TASK_ROOT"));
end
